#Supprimer les caractères qui se répètent dans une chaine

CH=str(input("< "))

def sup(ch) : 
    p = 1
    ok = True
    while ok :
        s = ch[:p] 
        x = s.find(ch[p])
        if x != -1 :
            ch = ch[:p] + ch[p+1:]
        else:
            p += 1
        ok = p <= len(ch)-1
    return (ch)

print(sup(CH))

